CREATE TABLE access_designations(id bigserial PRIMARY KEY,department text NOT NULL,name text NOT NULL,role text NOT NULL,permissions text[] NOT NULL DEFAULT '{}',features text[] NOT NULL DEFAULT '{}',version int NOT NULL DEFAULT 1,UNIQUE(department,name));
ALTER TABLE users ADD COLUMN designation_id bigint REFERENCES access_designations;
ALTER TABLE users ADD COLUMN inherit_designation boolean NOT NULL DEFAULT false;
ALTER TABLE company_setups ADD COLUMN assigned_to bigint REFERENCES users;
ALTER TABLE company_setups ADD COLUMN responsible_user_id bigint REFERENCES users;
UPDATE company_setups SET assigned_to=created_by,responsible_user_id=created_by;
ALTER TABLE company_setups ALTER COLUMN assigned_to SET NOT NULL;
ALTER TABLE company_setups ALTER COLUMN responsible_user_id SET NOT NULL;
ALTER TABLE companies ADD COLUMN setup_id bigint UNIQUE REFERENCES company_setups;
ALTER TABLE companies DROP CONSTRAINT companies_name_check;
ALTER TABLE companies ADD CONSTRAINT companies_name_check CHECK(length(name) BETWEEN 1 AND 150);
CREATE TABLE access_history(id bigserial PRIMARY KEY,actor_id bigint NOT NULL REFERENCES users,action text NOT NULL,subject_type text NOT NULL,subject_id bigint NOT NULL,detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER access_history_immutable BEFORE UPDATE OR DELETE ON access_history FOR EACH ROW EXECUTE FUNCTION protect_audit();
UPDATE users SET designation_id=(SELECT id FROM access_designations d WHERE d.role=users.role ORDER BY id LIMIT 1);
UPDATE users SET permissions=array_append(permissions,'view_orders') WHERE custom_permissions AND cardinality(permissions)>0 AND NOT ('view_orders'=ANY(permissions));
ALTER TABLE company_ports ADD COLUMN postal_code text NOT NULL DEFAULT '';
ALTER TABLE company_ports ADD COLUMN address text NOT NULL DEFAULT '';
ALTER TABLE company_setups ADD COLUMN business_mode text NOT NULL DEFAULT 'Not specified' CHECK(business_mode IN ('Not specified','Domestic','Import','Export','Import & export'));
ALTER TABLE company_field_definitions ADD COLUMN business_modes text[] NOT NULL DEFAULT '{}';
UPDATE company_field_definitions SET business_modes=ARRAY['Not specified','Import','Export','Import & export'] WHERE label='IEC' AND country='IN';
