INSERT INTO companies(name,kind,status,setup_id) SELECT legal_name,'Self','Approved',id FROM company_setups WHERE category='Internal' AND status='Approved' AND deleted_at IS NULL ON CONFLICT(name) DO NOTHING;
INSERT INTO access_history(actor_id,action,subject_type,subject_id,detail,created_at) SELECT actor_id,action,'User',user_id,detail,created_at FROM setup_access_history;
